# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TEMEL ENERJİ BİÇİMLERİ VE NİTELİKLERİ (FİZ.10.2.3)</text>\n  <rect x="22" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#1e40af">MEKANİK VE ISI ENERJİSİ</text>\n  <text x="32" y="88" font-size="10.8" fill="#1e3a8a">• Mekanik Enerji: Cisimlerin</text>\n  <text x="40" y="104" font-size="10.5" fill="#1e3a8a">hareketinden (kinetik) ve konu-</text>\n  <text x="40" y="120" font-size="10.5" fill="#1e3a8a">mundan/esnekliğinden (potansiyel)</text>\n  <text x="40" y="136" font-size="10.5" fill="#1e3a8a">kaynaklanan enerjidir.</text>\n  <text x="32" y="160" font-size="10.8" fill="#1e3a8a">• Isı (Termal) Enerjisi: Sıcaklık</text>\n  <text x="40" y="176" font-size="10.5" fill="#1e3a8a">farkı nedeniyle maddeler arasında</text>\n  <text x="40" y="192" font-size="10.5" fill="#1e3a8a">aktarılan enerjidir.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#166534">ELEKTRİK VE KİMYASAL ENERJİ</text>\n  <text x="255" y="88" font-size="10.8" fill="#14532d">• Elektrik Enerjisi: Elektrik yükle-</text>\n  <text x="263" y="104" font-size="10.5" fill="#14532d">rinin potansiyel farkı altında</text>\n  <text x="263" y="120" font-size="10.5" fill="#14532d">hareketiyle oluşan ve iletim hat-</text>\n  <text x="263" y="136" font-size="10.5" fill="#14532d">larıyla kolay taşınan enerjidir.</text>\n  <text x="255" y="160" font-size="10.8" fill="#14532d">• Kimyasal Enerji: Atom ve mole-</text>\n  <text x="263" y="176" font-size="10.5" fill="#14532d">küller arası bağlarda depolanan</text>\n  <text x="263" y="192" font-size="10.5" fill="#14532d">enerjidir (besin, pil, yakıt).</text>\n  <rect x="468" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="573" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#92400e">NÜKLEER VE IŞIK ENERJİSİ</text>\n  <text x="478" y="88" font-size="10.8" fill="#78350f">• Nükleer (Çekirdek) Enerjisi:</text>\n  <text x="486" y="104" font-size="10.5" fill="#78350f">Atom çekirdeğinin bölünmesi</text>\n  <text x="486" y="120" font-size="10.5" fill="#78350f">(fisyon) veya birleşmesiyle (füz-</text>\n  <text x="486" y="136" font-size="10.5" fill="#78350f">yon) açığa çıkan yoğun enerjidir.</text>\n  <text x="478" y="160" font-size="10.8" fill="#78350f">• Işık (Radyant) Enerjisi: Elektro-</text>\n  <text x="486" y="176" font-size="10.5" fill="#78350f">manyetik dalgalarla boşlukta</text>\n  <text x="486" y="192" font-size="10.5" fill="#78350f">yayılabilen ışıma enerjisidir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Ortak Özellik: Tüm enerji biçimleri skaler büyüklüktür, SI birimleri Joule (J)\'dür ve birbirine dönüşebilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ENERJİ DÖNÜŞÜM ZİNCİRLERİ VE KARŞILAŞTIRMA</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">SANTRALLERDE ENERJİ DÖNÜŞÜM ZİNCİRİ</text>\n  <text x="35" y="90" font-size="11.2" fill="#581c87">• Hidroelektrik Santral (HES):</text>\n  <text x="45" y="106" font-size="10.8" fill="#581c87">Potansiyel ⟶ Kinetik ⟶ Mekanik (Türbin) ⟶ Elektrik</text>\n  <text x="35" y="132" font-size="11.2" fill="#581c87">• Termik Santral (Kömür / Doğal Gaz):</text>\n  <text x="45" y="148" font-size="10.8" fill="#581c87">Kimyasal ⟶ Isı (Buhar) ⟶ Kinetik ⟶ Elektrik</text>\n  <text x="35" y="174" font-size="11.2" fill="#581c87">• Güneş Paneli (Fotovoltaik Pil):</text>\n  <text x="45" y="190" font-size="10.8" fill="#581c87">Işık (Radyant) Enerjisi ⟶ Doğrudan Elektrik Enerjisi</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">GÜNLÜK YAŞAM ARAÇLARINDA DÖNÜŞÜM</text>\n  <text x="370" y="90" font-size="11.2" fill="#881337">• Elektrikli Otomobil (Şarj ve Sürüş):</text>\n  <text x="380" y="106" font-size="10.8" fill="#881337">Elektrik ⟶ Kimyasal (Batarya) ⟶ Kinetik + Isı</text>\n  <text x="370" y="132" font-size="11.2" fill="#881337">• LED Lamba ve Aydınlatma:</text>\n  <text x="380" y="148" font-size="10.8" fill="#881337">Elektrik Enerjisi ⟶ Işık Enerjisi + Az Miktarda Isı</text>\n  <text x="370" y="174" font-size="11.2" fill="#881337">• Yeşil Bitkilerde Fotosentez:</text>\n  <text x="380" y="190" font-size="10.8" fill="#881337">Işık Enerjisi ⟶ Kimyasal Bağ Enerjisi (Glikoz)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Her enerji dönüşümünde toplam enerji korunur; ancak sürtünme ve direnç nedeniyle bir kısmı ısıya dönüşür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YENİLENEBİLİR VE YENİLENEMEZ ENERJİ KAYNAKLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">YENİLENEBİLİR (SÜRDÜRÜLEBİLİR) KAYNAKLAR</text>\n  <text x="35" y="88" font-size="11.2" fill="#064e3b">• Güneş, Rüzgâr ve Hidroelektrik (Su) Enerjisi</text>\n  <text x="35" y="112" font-size="11.2" fill="#064e3b">• Jeotermal (Yer altı sıcak su/buhar) Enerjisi</text>\n  <text x="35" y="136" font-size="11.2" fill="#064e3b">• Biyokütle (Organik atık) ve Dalga/Gelgit Enerjisi</text>\n  <text x="35" y="160" font-size="11.2" fill="#064e3b">• Hidrojen Enerjisi (Temiz yakıt teknolojisi)</text>\n  <text x="35" y="184" font-size="11.2" fill="#064e3b">• Avantaj: Doğada hızla yenilenir, karbon salımı</text>\n  <text x="45" y="200" font-size="11.2" fill="#064e3b">düşüktür, dışa bağımlılığı azaltır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">YENİLENEMEZ (TÜKENEBİLİR) KAYNAKLAR</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Fosil Yakıtlar: Kömür (linyit, taş kömürü),</text>\n  <text x="380" y="104" font-size="11.2" fill="#7c2d12">Petrol ve Doğal Gaz.</text>\n  <text x="370" y="128" font-size="11.2" fill="#7c2d12">• Çekirdek Kaynaklı: Nükleer Enerji (Uranyum</text>\n  <text x="380" y="144" font-size="11.2" fill="#7c2d12">ve Toryum gibi radyoaktif mineraller).</text>\n  <text x="370" y="168" font-size="11.2" fill="#7c2d12">• Dezavantaj: Rezervleri sınırlıdır; fosil yakıtlar</text>\n  <text x="380" y="184" font-size="11.2" fill="#7c2d12">sera gazı (CO₂) salımıyla küresel ısınmaya yol açar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Enerji verimliliği yüksek (A sınıfı) cihazlar kullanmak ve yalıtım yapmak sürdürülebilirlik için esastır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
